from pathlib import Path
import json

events_dir = Path('.pipeline/events')
if events_dir.exists():
    for p in events_dir.glob('*.log'):
        lines = p.read_text().splitlines()
        out = []
        for line in lines:
            if line.startswith('{'):
                try:
                    ev = json.loads(line)
                except json.JSONDecodeError:
                    out.append(line)
                    continue
                if ev.get('action') in ('LOCK', 'UNLOCK'):
                    continue
            out.append(line)
        p.write_text(('\n'.join(out) + '\n') if out else '')
